(37713, 'Joshua 2:18', 'Joshua', 2, 18, 'کله چې مونږ ستاسو په خاوره باندې حمله وکړه، دا سور مزی په هغې کړکۍ باندې وتړه چې تا ورباندې راښکته کړو. خپل پلار، مور، ورونه او د خپل پلار ټوله کورنۍ په خپل کور کې سره راټول کړه.', 'کله چې مونز ستاسو په خاوره باندې حمله وکره، دا سور مزی په هغې کرکی باندې وتره چې تا ورباندې راشکته کرو. خپل پلار، مور، ورونه او د خپل پلار توله کورنی په خپل کور کې سره راتول کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_2_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37714, 'Joshua 2:19', 'Joshua', 2, 19, 'که چېرې څوک ستا د کور څخه ووځي، نو د هغه خون به د هغه په خپله غاړه وي او مسوولیت به یې زمونږ په غاړه نه وي. خو که چېرې ستا په کور کې چاته زیان ورسیږي، بیا به مسوولیت زمونږ په غاړه وي.', 'که چېرې چوک ستا د کور چخه ووجی، نو د هغه خون به د هغه په خپله غاره وی او مسوولیت به یې زمونز په غاره نه وی. خو که چېرې ستا په کور کې چاته زیان ورسیزی، بیا به مسوولیت زمونز په غاره وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_2_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37715, 'Joshua 2:20', 'Joshua', 2, 20, 'خو که چېرې چاته ووایې چې مونږ څه کوو، نو بیا به مونږ مجبور نه یو په هغې وعدې باندې ټینګ پاتې شو چې تا په مونږ باندې کړې وه.»', 'خو که چېرې چاته ووایې چې مونز چه کوو، نو بیا به مونز مجبور نه یو په هغې وعدې باندې تینګ پاتې شو چې تا په مونز باندې کرې وه.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_2_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37716, 'Joshua 2:21', 'Joshua', 2, 21, 'راحاب دا خبره ومنله او هغوی یې رخصت کړل. کله چې هغوی لاړل، هغې په کړکۍ باندې سور مزی وتړه.', 'راحاب دا خبره ومنله او هغوی یې رخصت کرل. کله چې هغوی لارل، هغې په کرکی باندې سور مزی وتره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_2_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37717, 'Joshua 2:22', 'Joshua', 2, 22, 'هغه جاسوسان غونډیو ته لاړل او پټ شول. د پاچا کسانو درې ورځې د هغې سیمې ټولې لارې ولټولې، خو هغوی یې پیدا نه کړل، نو هغوی بېرته اریحا ته راستانه شول.', 'هغه جاسوسان غوندیو ته لارل او پت شول. د پاچا کسانو درې ورجې د هغې سیمې تولې لارې ولتولې، خو هغوی یې پیدا نه کرل، نو هغوی بېرته اریحا ته راستانه شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_2_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37718, 'Joshua 2:23', 'Joshua', 2, 23, 'بیا هغه دوه جاسوسان د غونډیو څخه راښکته شول، د اردن د سیند څخه تېر شول او بېرته یوشع ته ورغلل. هرڅه چې په هغوی باندې تېر شوي وو هغه ته یې بیان کړل.', 'بیا هغه دوه جاسوسان د غوندیو چخه راشکته شول، د اردن د سیند چخه تېر شول او بېرته یوشع ته ورغلل. هرچه چې په هغوی باندې تېر شوی وو هغه ته یې بیان کرل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37719, 'Joshua 2:24', 'Joshua', 2, 24, 'هغوی یوشع ته وویل: «مونږ باور لرو چې څښتن مونږ ته هغه ټول هېواد راکړی دی. د هغه ځای ټول خلک زمونږ څخه سخت وېریږي.»', 'هغوی یوشع ته وویل: «مونز باور لرو چې چشتن مونز ته هغه تول هېواد راکری دی. د هغه جای تول خلک زمونز چخه سخت وېریزی.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37720, 'Hosea 6:1', 'Hosea', 6, 1, 'خلک وایي: «راځئ چې د څښتن خواته راوګرځو! هغه مونږ ټوټې ټوټې کړي یو، خو اوس به مونږ روغ کړي. هغه مونږ زخمي کړي یو، خو اوس به زمونږ په زخمونو باندې پټۍ کېږدي.', 'خلک وایی: «راجی چې د چشتن خواته راوګرجو! هغه مونز توتې توتې کری یو، خو اوس به مونز روغ کری. هغه مونز زخمی کری یو، خو اوس به زمونز په زخمونو باندې پتی کېزدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_6_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37721, 'Hosea 6:2', 'Hosea', 6, 2, 'په ډېر کم وخت کې به هغه مونږ ته نوی ژوند راکړي او مونږ به راپورته کړي، ترڅو د هغه په حضور کې ژوند وکړو.', 'په دېر کم وخت کې به هغه مونز ته نوی ژوند راکری او مونز به راپورته کری، ترچو د هغه په حضور کې ژوند وکرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Hosea_6_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
