(37754, 'Leviticus 16:24', 'Leviticus', 16, 24, 'هغه به په یو سپېڅلي ځای کې غسل وکړي او خپل عادي کالي به واغوندي. بیا به هغه دباندې راووځي او یوه سوځېدونکې نذرانه به د ځان او یوه د قوم دپاره قرباني کړي، د دې په خاطر چې د خپل ځان او د هغوی دپاره کفاره ادا کړي.', 'هغه به په یو سپېچلی جای کې غسل وکری او خپل عادی کالی به واغوندی. بیا به هغه دباندې راووجی او یوه سوجېدونکې نذرانه به د جان او یوه د قوم دپاره قربانی کری، د دې په خاطر چې د خپل جان او د هغوی دپاره کفاره ادا کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37755, 'Leviticus 16:25', 'Leviticus', 16, 25, 'همدارنګه هغه به د قربانۍ په ځای باندې د حیوان وازګه چې د ګناه د نذرانې دپاره ده، وسوځوي.', 'همدارنګه هغه به د قربانی په جای باندې د حیوان وازګه چې د ګناه د نذرانې دپاره ده، وسوجوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37756, 'Leviticus 16:26', 'Leviticus', 16, 26, 'هغه سړی چې سېرلی یې په دښته کې عزازیل ته ورپرېښود، باید کمپ ته د بېرته راتګ څخه مخکې خپل کالي ووینځي او غسل دې وکړي.', 'هغه سری چې سېرلی یې په دشته کې عزازیل ته ورپرېشود، باید کمپ ته د بېرته راتګ چخه مخکې خپل کالی ووینجی او غسل دې وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37757, 'Leviticus 16:27', 'Leviticus', 16, 27, 'هغه غویی او سېرلی چې د ګناه د نذرانو دپاره ورڅخه کار واخیستل شو او د هغو وینه د کفارې د ادا کولو دپاره ډېر سپېڅلي ځای ته راوړل شوه، باید د کمپ څخه دباندې یووړل شي. د هغو پوستکي، غوښه او خوشایي دې وسوځول شي.', 'هغه غویی او سېرلی چې د ګناه د نذرانو دپاره ورچخه کار واخیستل شو او د هغو وینه د کفارې د ادا کولو دپاره دېر سپېچلی جای ته راورل شوه، باید د کمپ چخه دباندې یوورل شی. د هغو پوستکی، غوشه او خوشایی دې وسوجول شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37758, 'Leviticus 16:28', 'Leviticus', 16, 28, 'کوم سړی چې هغه سوځوي باید خپل کالي ووینځي او غسل دې وکړي، له هغې وروسته هغه کمپ ته ننوتلی شي.', 'کوم سری چې هغه سوجوی باید خپل کالی ووینجی او غسل دې وکری، له هغې وروسته هغه کمپ ته ننوتلی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37759, 'Leviticus 16:29', 'Leviticus', 16, 29, 'په لاندېنیو مقرراتو باندې دې د تل دپاره عمل وشي. د اوومې میاشتې په لسمه ورځ تاسو ټول اسراییلیان او هغه پردي خلک چې ستاسو په منځ کې اوسیږي، باید روژه ونیسئ او هېڅ کار باید ونه کړئ،', 'په لاندېنیو مقرراتو باندې دې د تل دپاره عمل وشی. د اوومې میاشتې په لسمه ورج تاسو تول اسراییلیان او هغه پردی خلک چې ستاسو په منج کې اوسیزی، باید روژه ونیسی او هېچ کار باید ونه کری،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37760, 'Leviticus 16:30', 'Leviticus', 16, 30, 'ځکه چې په دې ورځ به ستاسو د پاکولو دپاره کفاره ادا شي. بیا به تاسو د څښتن په حضور کې د خپلو ټولو ګناهونو څخه پاک شئ.', 'جکه چې په دې ورج به ستاسو د پاکولو دپاره کفاره ادا شی. بیا به تاسو د چشتن په حضور کې د خپلو تولو ګناهونو چخه پاک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_16_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839);